:root {
  --bg: #1a1a2e;
  --panel: #16213e;
  --accent: #e94560;
  --text: #eaeaea;
  --muted: #9a9ab0;
  --border: #3a3a5c;
  --focus: #f9d342;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  min-height: 100vh;
  display: grid;
  place-items: center;
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  padding: 16px;
}

.board {
  width: 100%;
  max-width: 960px;
  background: var(--panel);
  border: 3px solid var(--border);
  box-shadow: 6px 6px 0 #0f0f1f;
  padding: 20px;
}

.board-title {
  margin: 0 0 16px;
  font-size: 1.5rem;
  letter-spacing: 1px;
  text-transform: uppercase;
  color: var(--accent);
  text-shadow: 2px 2px 0 #0f0f1f;
}

.add-form {
  display: flex;
  gap: 8px;
  margin-bottom: 20px;
  flex-wrap: wrap;
}

#card-input {
  flex: 1 1 200px;
  min-width: 0;
  padding: 10px 12px;
  font: inherit;
  color: var(--text);
  background: var(--bg);
  border: 2px solid var(--border);
}

#card-input:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

button {
  font: inherit;
  cursor: pointer;
  color: var(--text);
  background: var(--bg);
  border: 2px solid var(--border);
  padding: 8px 12px;
  transition: background 0.1s, transform 0.05s;
}

button:hover { background: #24244a; }
button:active { transform: translate(1px, 1px); }
button:focus-visible { outline: 3px solid var(--focus); outline-offset: 2px; }

#add-btn {
  background: var(--accent);
  border-color: var(--accent);
  font-weight: 600;
}
#add-btn:hover { background: #ff5c78; }

.columns {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
}

.column {
  background: var(--bg);
  border: 2px solid var(--border);
  padding: 10px;
  min-height: 180px;
}

.col-title {
  margin: 0 0 10px;
  font-size: 1rem;
  display: flex;
  justify-content: space-between;
  align-items: center;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.count {
  background: var(--accent);
  color: #fff;
  font-size: 0.8rem;
  padding: 1px 8px;
  border: 2px solid #0f0f1f;
}

.card-list { display: flex; flex-direction: column; gap: 8px; }

.card {
  background: var(--panel);
  border: 2px solid var(--border);
  padding: 8px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  word-break: break-word;
}

.card-text {
  font-size: 0.95rem;
  line-height: 1.3;
}

.card-actions {
  display: flex;
  gap: 4px;
  justify-content: flex-end;
}

.card-actions button {
  padding: 2px 8px;
  font-size: 0.9rem;
  line-height: 1.4;
}

.card-actions button:disabled {
  opacity: 0.35;
  cursor: not-allowed;
}

.visually-hidden {
  position: absolute;
  width: 1px; height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}

@media (max-width: 600px) {
  .columns { grid-template-columns: 1fr; }
  .board { padding: 14px; }
}

(function () {
  'use strict';

  const COLS = ['todo', 'doing', 'done'];
  const LABELS = { todo: 'To do', doing: 'Doing', done: 'Done' };
  let cards = [];
  let nextId = 1;

  const form = document.getElementById('add-form');
  const input = document.getElementById('card-input');
  const lists = {
    todo: document.getElementById('list-todo'),
    doing: document.getElementById('list-doing'),
    done: document.getElementById('list-done')
  };
  const counts = {
    todo: document.getElementById('count-todo'),
    doing: document.getElementById('count-doing'),
    done: document.getElementById('count-done')
  };

  function render() {
    COLS.forEach(function (col) {
      lists[col].innerHTML = '';
      const colCards = cards.filter(function (c) { return c.col === col; });
      counts[col].textContent = colCards.length;
      colCards.forEach(function (card) {
        lists[col].appendChild(buildCard(card));
      });
    });
  }

  function buildCard(card) {
    const el = document.createElement('div');
    el.className = 'card';
    el.setAttribute('role', 'listitem');

    const text = document.createElement('span');
    text.className = 'card-text';
    text.textContent = card.text;
    el.appendChild(text);

    const actions = document.createElement('div');
    actions.className = 'card-actions';

    const idx = COLS.indexOf(card.col);
    const left = makeBtn('\u25C0', 'Move "' + card.text + '" left', idx === 0);
    left.addEventListener('click', function () { move(card.id, -1); });

    const right = makeBtn('\u25B6', 'Move "' + card.text + '" right', idx === COLS.length - 1);
    right.addEventListener('click', function () { move(card.id, 1); });

    const del = makeBtn('\u2715', 'Delete "' + card.text + '"', false);
    del.addEventListener('click', function () { remove(card.id); });

    actions.appendChild(left);
    actions.appendChild(right);
    actions.appendChild(del);
    el.appendChild(actions);
    return el;
  }

  function makeBtn(label, aria, disabled) {
    const b = document.createElement('button');
    b.type = 'button';
    b.textContent = label;
    b.setAttribute('aria-label', aria);
    b.disabled = disabled;
    return b;
  }

  function move(id, dir) {
    const card = cards.find(function (c) { return c.id === id; });
    if (!card) return;
    const next = COLS.indexOf(card.col) + dir;
    if (next < 0 || next >= COLS.length) return;
    card.col = COLS[next];
    render();
  }

  function remove(id) {
    cards = cards.filter(function (c) { return c.id !== id; });
    render();
  }

  form.addEventListener('submit', function (e) {
    e.preventDefault();
    const text = input.value.trim();
    if (!text) { input.focus(); return; }
    cards.push({ id: nextId++, text: text, col: 'todo' });
    input.value = '';
    input.focus();
    render();
  });

  render();
})();
